/**
 * Neutral 1200×630 JPEG used when an active QR memory has no real social
 * preview image (audio, legacy HEIC/HEIF, or a video without a poster).
 * It is intentionally family-agnostic: no caption, date, member name, or
 * internal identifier can be written into a chat app's external preview cache.
 *
 * Source: the owner-approved `src/brand-poster-source.svg` artwork rendered
 * to JPEG for this Worker. Kept as a small embedded data module so Wrangler
 * bundles it without a separate public asset origin.
 */
const BRAND_POSTER_BASE64 = '';

function decodeBase64(value: string): ArrayBuffer {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes.buffer;
}

export const BRAND_POSTER_CONTENT_TYPE = 'image/jpeg';
export const BRAND_POSTER_BYTES = decodeBase64(BRAND_POSTER_BASE64);
